/**
 * Surface Discovery Engine — Core Types
 * 
 * Agnostic type system for proactive surface discovery.
 * Works for any target: websites, codebases, APIs, email templates, docs, etc.
 */

// =============================================================================
// SURFACE TYPES
// =============================================================================

export enum SurfaceType {
  WEB_PAGE = 'web_page',
  API_ENDPOINT = 'api_endpoint',
  EMAIL_TEMPLATE = 'email_template',
  CHAT_CONFIG = 'chat_config',
  CODE_COMPONENT = 'code_component',
  DOCUMENTATION = 'documentation',
  MOBILE_SCREEN = 'mobile_screen',
  SOCIAL_POST = 'social_post',
  AD_COPY = 'ad_copy',
  SLIDE_DECK = 'slide_deck',
  OTHER = 'other',
}

export enum DiscoveryStatus {
  DISCOVERED = 'discovered',   // Found but not reviewed
  REVIEWED = 'reviewed',       // Analyzed by cognitive systems
  STALE = 'stale',             // Content changed since review
  DEAD = 'dead',               // Surface no longer exists
  IGNORED = 'ignored',         // Explicitly excluded from governance
}

// =============================================================================
// DISCOVERED SURFACE
// =============================================================================

export interface DiscoveredSurfaceData {
  surfaceId: string;           // Deterministic ID (hash of url + type + customerId)
  url: string;                 // The surface location/endpoint/path
  surfaceType: SurfaceType;    // What kind of surface
  title?: string;              // Human-readable name
  contentHash: string;         // Hash of current content for change detection
  contentSnapshot?: string;    // Extracted text content for review
  lastSeen: Date;              // When this surface was last discovered
  metadata: Record<string, unknown>;
  parentSurfaceId?: string;    // For hierarchical surfaces
  discoverySource: string;     // Which adapter found this
}

// =============================================================================
// COVERAGE
// =============================================================================

export interface CoverageReportData {
  customerId: string;
  totalSurfaces: number;
  reviewedSurfaces: number;
  staleSurfaces: number;
  deadSurfaces: number;
  ignoredSurfaces: number;
  overallCoverage: number;     // 0-1
  coverageByType: Record<string, { total: number; reviewed: number; coverage: number }>;
  gapAreas: SurfaceGap[];
  lastSweepDate?: Date;
  computedAt: Date;
}

export interface SurfaceGap {
  surfaceType: string;
  unreviewedCount: number;
  staleCount: number;
  oldestUnseen?: Date;
  priority: 'low' | 'medium' | 'high' | 'critical';
  suggestedAction: string;
}

// =============================================================================
// DISCOVERY ADAPTER INTERFACE
// =============================================================================

export interface AdapterConfig {
  type: string;
  enabled: boolean;
  config: Record<string, unknown>;
}

export interface DiscoveryAdapter {
  readonly type: string;
  readonly name: string;

  /**
   * Discover all surfaces for a customer.
   * Returns a list of discovered surfaces — the engine handles dedup and inventory.
   */
  discover(customerId: string, config: AdapterConfig): Promise<DiscoveredSurfaceData[]>;

  /**
   * Verify if a specific surface still exists and get its current content hash.
   * Used by the change detector to identify stale/dead surfaces.
   */
  verify(surface: DiscoveredSurfaceData): Promise<{
    exists: boolean;
    contentHash?: string;
    contentSnapshot?: string;
    metadata?: Record<string, unknown>;
  }>;

  /**
   * Validate adapter configuration before running discovery.
   */
  validateConfig(config: AdapterConfig): Promise<{ valid: boolean; errors?: string[] }>;
}

// =============================================================================
// DISCOVERY CONFIG
// =============================================================================

export interface DiscoveryConfigData {
  customerId: string;
  adapters: AdapterConfig[];
  coverageThresholds: {
    sweepTrigger: number;        // Trigger sweep when coverage drops below this (0-1)
    criticalThreshold: number;   // Mark as critical below this (0-1)
    staleThresholdDays: number;  // Mark as stale after this many days without re-review
  };
  exclusionPatterns: string[];   // Regex patterns to ignore
}

// =============================================================================
// SWEEP
// =============================================================================

export type SweepTriggerType = 'coverage_drop' | 'stale_surfaces' | 'positioning_change' | 'scheduled' | 'manual';

export interface SweepEvaluation {
  shouldTrigger: boolean;
  reasons: string[];
  priority: 'low' | 'medium' | 'high' | 'critical';
  affectedSurfaces: number;
  coverageAtEvaluation: number;
}

export interface SweepResult {
  sweepId: number;
  surfacesReviewed: number;
  surfacesRemediated: number;
  issuesFound: number;
  durationMs: number;
}

// =============================================================================
// CHANGE DETECTION
// =============================================================================

export interface ChangeDetectionResult {
  changedSurfaces: Array<{ surfaceId: string; oldHash: string; newHash: string }>;
  newSurfaces: Array<{ surfaceId: string; url: string; surfaceType: SurfaceType }>;
  deadSurfaces: Array<{ surfaceId: string; url: string; lastSeen: Date }>;
  totalChecked: number;
  durationMs: number;
}

