  // Parse the event
  const event = parseWebhookEvent(headers, body);

  governanceLog.info(`[Webhook] Received ${event.provider}/${event.eventType} for ${customerId}`);

  // Check if this event should trigger discovery
  if (!shouldTriggerDiscovery(event)) {
    governanceLog.info(`[Webhook] Event filtered out — not a trigger event`);
    return {
      accepted: true,
      eventType: event.eventType,
      pipelineTriggered: false,
      reason: `Event type ${event.eventType} does not trigger discovery`,
    };
  }

  // Trigger the full discovery pipeline
  governanceLog.info(`[Webhook] Triggering discovery pipeline for ${customerId}`);
  try {
    const config = getDefaultDogfoodConfig(customerId);

    // If deployment URL is available, add it as a discovery target
    if (event.deploymentUrl) {
      config.adapters.push({
        type: 'web_crawler',
        enabled: true,
        config: {
          baseUrl: event.deploymentUrl,
          maxDepth: 3,
          includePatterns: ['/**'],
          excludePatterns: ['/api/**', '/admin/**'],
        },
      });
    }

    const pipelineResult: ProactiveCoherencePipelineResult = await runProactiveCoherencePipeline(customerId, config);

    return {
      accepted: true,
      eventType: event.eventType,
      pipelineTriggered: true,
      pipelineResult: {
        surfacesDiscovered: pipelineResult.discovery?.totalDiscovered || 0,
        coverageRatio: pipelineResult.coverageReport?.ratio,
        sweepTriggered: !!pipelineResult.sweep,
        remediationsApplied: pipelineResult.remediationResults?.applied || 0,
        gateStatus: pipelineResult.evaluation?.priority,
      },
    };
  } catch (error) {
    governanceLog.error(`[Webhook] Pipeline error:`, error);
    return {
      accepted: true,
      eventType: event.eventType,
      pipelineTriggered: true,
      reason: `Pipeline execution failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
    };
  }
}
